@page "/book-appointment"
@rendermode InteractiveServer
@using System.ComponentModel.DataAnnotations
@using sv_018df02cafa14172818739ff80ad7ba0.Models
@using sv_018df02cafa14172818739ff80ad7ba0.Services
@inject AppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>
<h3>Book an Appointment</h3>

@if (isBooked)
{
    <div class="alert alert-success mt-3">
        <h4>Appointment Confirmed!</h4>
        <p>
            <strong>@model.PatientName</strong>, your appointment with
            <strong>@model.PreferredDoctor</strong> on
            <strong>@model.AppointmentDate?.ToString("D")</strong> at
            <strong>@model.TimeSlot</strong> has been booked.
        </p>
    </div>
}
else
{
    <EditForm EditContext="editContext">
        <CustomValidator @ref="customValidator" />

        <fieldset class="mb-4">
            <legend>Patient Information</legend>

            <div class="mb-3">
                <label class="form-label">Patient Name</label>
                <InputText @bind-Value="model.PatientName" class="form-control" />
                <ValidationMessage For="() => model.PatientName" />
            </div>

            <div class="mb-3">
                <label class="form-label">Email</label>
                <InputText @bind-Value="model.Email" class="form-control" />
                <ValidationMessage For="() => model.Email" />
            </div>

            <div class="mb-3">
                <label class="form-label">Phone</label>
                <InputText @bind-Value="model.Phone" class="form-control" />
                <ValidationMessage For="() => model.Phone" />
            </div>

            <div class="mb-3">
                <label class="form-label">Insurance Provider</label>
                <InputSelect @bind-Value="model.InsuranceProvider" class="form-select">
                    <option value="">-- Select Insurance --</option>
                    <option value="Aetna">Aetna</option>
                    <option value="BlueCross">BlueCross</option>
                    <option value="Cigna">Cigna</option>
                    <option value="UnitedHealth">UnitedHealth</option>
                    <option value="None">None</option>
                </InputSelect>
                <ValidationMessage For="() => model.InsuranceProvider" />
            </div>

            <button type="button" class="btn btn-primary" @onclick="CheckAvailability" disabled="@isChecking">
                @(isChecking ? "Checking..." : "Check Availability")
            </button>
        </fieldset>

        @if (showStep2)
        {
            <fieldset class="mb-4">
                <legend>Appointment Details</legend>

                <div class="mb-3">
                    <label class="form-label">Preferred Doctor</label>
                    <InputSelect @bind-Value="model.PreferredDoctor" class="form-select"
                                 @bind-Value:after="OnDoctorChanged">
                        <option value="">-- Select Doctor --</option>
                        @foreach (var doctor in doctors)
                        {
                            <option value="@doctor">@doctor</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => model.PreferredDoctor" />
                </div>

                <div class="mb-3">
                    <label class="form-label">Appointment Date</label>
                    <InputDate @bind-Value="model.AppointmentDate" class="form-control"
                               @bind-Value:after="OnDateChanged" />
                    <ValidationMessage For="() => model.AppointmentDate" />
                </div>

                <div class="mb-3">
                    <label class="form-label">Time Slot</label>
                    <InputSelect @bind-Value="model.TimeSlot" class="form-select">
                        <option value="">-- Select Time Slot --</option>
                        @foreach (var slot in availableSlots)
                        {
                            <option value="@slot">@slot</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => model.TimeSlot" />
                </div>

                <div class="mb-3">
                    <label class="form-label">Reason for Visit</label>
                    <InputTextArea @bind-Value="model.ReasonForVisit" class="form-control" rows="3" />
                    <ValidationMessage For="() => model.ReasonForVisit" />
                </div>

                <button type="button" class="btn btn-success" @onclick="BookAppointment" disabled="@isSubmitting">
                    @(isSubmitting ? "Booking..." : "Book Appointment")
                </button>
            </fieldset>
        }
    </EditForm>
}

@code {
    private AppointmentModel model = new();
    private EditContext editContext = null!;
    private ValidationMessageStore messageStore = null!;
    private CustomValidator? customValidator;

    private bool showStep2;
    private bool isChecking;
    private bool isSubmitting;
    private bool isBooked;

    private List<string> doctors = [];
    private List<string> availableSlots = [];

    private static readonly string[] Step1Fields =
    [
        nameof(AppointmentModel.PatientName),
        nameof(AppointmentModel.Email),
        nameof(AppointmentModel.Phone),
        nameof(AppointmentModel.InsuranceProvider)
    ];

    private static readonly string[] AllFields =
    [
        nameof(AppointmentModel.PatientName),
        nameof(AppointmentModel.Email),
        nameof(AppointmentModel.Phone),
        nameof(AppointmentModel.InsuranceProvider),
        nameof(AppointmentModel.PreferredDoctor),
        nameof(AppointmentModel.AppointmentDate),
        nameof(AppointmentModel.TimeSlot),
        nameof(AppointmentModel.ReasonForVisit)
    ];

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(model);
        messageStore = new ValidationMessageStore(editContext);
        editContext.OnFieldChanged += HandleFieldChanged;
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void HandleFieldChanged(object? sender, FieldChangedEventArgs e)
    {
        messageStore.Clear(e.FieldIdentifier);
        editContext.NotifyValidationStateChanged();
    }

    private bool ValidateFields(string[] fields)
    {
        foreach (var field in fields)
            messageStore.Clear(editContext.Field(field));

        var isValid = true;

        foreach (var field in fields)
        {
            var prop = typeof(AppointmentModel).GetProperty(field)!;
            var value = prop.GetValue(model);
            var results = new List<ValidationResult>();
            var ctx = new ValidationContext(model) { MemberName = field };

            if (!Validator.TryValidateProperty(value, ctx, results))
            {
                foreach (var result in results)
                    messageStore.Add(editContext.Field(field), result.ErrorMessage!);
                isValid = false;
            }
        }

        editContext.NotifyValidationStateChanged();
        return isValid;
    }

    private async Task CheckAvailability()
    {
        if (!ValidateFields(Step1Fields))
            return;

        isChecking = true;
        try
        {
            var errors = await AppointmentService.ValidatePatientAsync(model);
            if (errors.Count > 0)
            {
                customValidator!.DisplayErrors(errors);
                return;
            }
            showStep2 = true;
        }
        finally
        {
            isChecking = false;
        }
    }

    private async Task OnDoctorChanged()
    {
        await LoadAvailableSlots();
    }

    private async Task OnDateChanged()
    {
        await LoadAvailableSlots();
    }

    private async Task LoadAvailableSlots()
    {
        if (!string.IsNullOrEmpty(model.PreferredDoctor) && model.AppointmentDate.HasValue)
        {
            availableSlots = await AppointmentService.GetAvailableSlotsAsync(
                model.PreferredDoctor, model.AppointmentDate.Value);
            model.TimeSlot = null;
        }
        else
        {
            availableSlots = [];
        }
    }

    private async Task BookAppointment()
    {
        if (!ValidateFields(AllFields))
            return;

        isSubmitting = true;
        try
        {
            var errors = await AppointmentService.ValidatePatientAsync(model);
            if (errors.Count > 0)
            {
                customValidator!.DisplayErrors(errors);
                return;
            }
            isBooked = true;
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

